import React, { useState } from 'react';
import { Outlet, NavLink, useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import './Layout.css';

const ROLE_LABELS = {
  super_admin:             'Administrateur Système',
  admin:                   'Administrateur',
  direction:               'Direction',
  assistant_admin:         'Assistant Administration',
  rh:                      'Ressources Humaines',
  responsable_stock:       'Responsable Stock',
  responsable_volontaires: 'Responsable Volontaires',
  responsable_bcc:         'Responsable BCC',
  coordinateur:            'Coordinateur',
  utilisateur:             'Utilisateur',
};

const ADMIN_ROLES = ['super_admin', 'admin'];
const PERSONNEL_ROLES = ['super_admin', 'admin', 'assistant_admin', 'rh', 'direction'];
const STOCK_ROLES = ['super_admin', 'admin', 'responsable_stock', 'direction'];
const VOL_ROLES = ['super_admin', 'admin', 'responsable_volontaires', 'direction'];

export default function Layout() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const [collapsed,  setCollapsed]  = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);

  const handleLogout = () => { logout(); navigate('/login'); };

  // Vérifie si le rôle a accès — les admins ont tout
  const can = (roles) => {
    if (!user) return false;
    const r = user.role || '';
    if (r === 'admin' || r === 'super_admin') return true;
    return roles.includes(r);
  };

  return (
    <div className={`layout ${collapsed ? 'sidebar-collapsed' : ''} ${mobileOpen ? 'mobile-open' : ''}`}>
      {mobileOpen && <div className="overlay" onClick={() => setMobileOpen(false)} />}

      {/* ── SIDEBAR ─────────────────────────────────────── */}
      <aside className="sidebar">
        <div className="sidebar-header">
          <div className="logo">
            {!collapsed && (
              <div className="logo-text-only">
                <span style={{ color:'#c9a84c', fontSize:'1.1rem' }}>✝</span>
                <span style={{ color:'white', fontFamily:"'Playfair Display',serif", fontWeight:700, fontSize:'0.9rem', marginLeft:8 }}>LHM Madagascar</span>
              </div>
            )}
            {collapsed && (
              <span style={{ color:'#c9a84c', fontSize:'1.2rem' }}>✝</span>
            )}
          </div>
          <button className="collapse-btn" onClick={() => setCollapsed(!collapsed)} title="Réduire">
            {collapsed ? '›' : '‹'}
          </button>
        </div>

        <nav className="sidebar-nav">

          {/* Tableau de bord — toujours visible */}
          <NavLink to="/" end
            className={({ isActive }) => `nav-item ${isActive ? 'active' : ''}`}
            onClick={() => setMobileOpen(false)}
            title={collapsed ? 'Tableau de bord' : ''}>
            <span className="nav-icon">📊</span>
            {!collapsed && <span className="nav-label">Tableau de bord</span>}
          </NavLink>

          {/* Personnel */}
          {can(PERSONNEL_ROLES) && (
            <NavLink to="/personnel"
              className={({ isActive }) => `nav-item ${isActive ? 'active' : ''}`}
              onClick={() => setMobileOpen(false)}
              title={collapsed ? 'Personnel' : ''}>
              <span className="nav-icon">👥</span>
              {!collapsed && <span className="nav-label">Personnel</span>}
            </NavLink>
          )}

          {/* Absences */}
          {can(PERSONNEL_ROLES) && (
            <NavLink to="/absences"
              className={({ isActive }) => `nav-item ${isActive ? 'active' : ''}`}
              onClick={() => setMobileOpen(false)}
              title={collapsed ? 'Absences & Congés' : ''}>
              <span className="nav-icon">📅</span>
              {!collapsed && <span className="nav-label">Absences &amp; Congés</span>}
            </NavLink>
          )}

          {/* Volontaires */}
          {can(VOL_ROLES) && (
            <NavLink to="/volontaires"
              className={({ isActive }) => `nav-item ${isActive ? 'active' : ''}`}
              onClick={() => setMobileOpen(false)}
              title={collapsed ? 'Volontaires' : ''}>
              <span className="nav-icon">🤝</span>
              {!collapsed && <span className="nav-label">Volontaires</span>}
            </NavLink>
          )}

          {/* Stock */}
          {can(STOCK_ROLES) && (
            <NavLink to="/stock"
              className={({ isActive }) => `nav-item ${isActive ? 'active' : ''}`}
              onClick={() => setMobileOpen(false)}
              title={collapsed ? 'Gestion du Stock' : ''}>
              <span className="nav-icon">📦</span>
              {!collapsed && <span className="nav-label">Gestion du Stock</span>}
            </NavLink>
          )}

          {/* Projets — toujours visible */}
          <NavLink to="/projets"
            className={({ isActive }) => `nav-item ${isActive ? 'active' : ''}`}
            onClick={() => setMobileOpen(false)}
            title={collapsed ? 'Projets' : ''}>
            <span className="nav-icon">🎯</span>
            {!collapsed && <span className="nav-label">Projets</span>}
          </NavLink>

          {/* ── Séparateur ── */}
          <div className="nav-separator" />

          {/* BCC — toujours visible pour tous les utilisateurs connectés */}
          <NavLink to="/bcc"
            className={({ isActive }) => `nav-item ${isActive ? 'active' : ''}`}
            onClick={() => setMobileOpen(false)}
            title={collapsed ? 'BCC' : ''}>
            <span className="nav-icon">📖</span>
            {!collapsed && <span className="nav-label">BCC</span>}
          </NavLink>

          {/* ── Séparateur ── */}
          <div className="nav-separator" />

          {/* Utilisateurs */}
          {can(ADMIN_ROLES) && (
            <NavLink to="/utilisateurs"
              className={({ isActive }) => `nav-item ${isActive ? 'active' : ''}`}
              onClick={() => setMobileOpen(false)}
              title={collapsed ? 'Utilisateurs' : ''}>
              <span className="nav-icon">🔐</span>
              {!collapsed && <span className="nav-label">Utilisateurs</span>}
            </NavLink>
          )}

        </nav>

        <div className="sidebar-footer">
          {!collapsed && (
            <div className="user-info">
              <div className="user-avatar">
                {(user?.name || user?.username || '?')[0].toUpperCase()}
              </div>
              <div className="user-details">
                <span className="user-name">{user?.name || user?.username}</span>
                <span className="user-role">{ROLE_LABELS[user?.role] || user?.role}</span>
              </div>
            </div>
          )}
          <button className="logout-btn" onClick={handleLogout} title="Se déconnecter">
            <span>🚪</span>
            {!collapsed && <span>Déconnexion</span>}
          </button>
        </div>
      </aside>

      {/* ── MAIN ─────────────────────────────────────────── */}
      <div className="main-wrapper">
        <header className="topbar">
          <button className="mobile-menu-btn" onClick={() => setMobileOpen(!mobileOpen)}>☰</button>
          <div className="topbar-left">
            <h1 className="page-title" id="page-title">Bienvenue</h1>
          </div>
          <div className="topbar-right">
            <div className="topbar-user">
              <div className="user-avatar-sm">
                {(user?.name || user?.username || '?')[0].toUpperCase()}
              </div>
              <span className="topbar-name">{user?.name || user?.username}</span>
            </div>
          </div>
        </header>
        <main className="main-content"><Outlet /></main>
      </div>
    </div>
  );
}
